/**
 * A7-01 (DATA rounds/round-02/outputs/DATA/s4-a7-reconciliation.md; ARC openapi-0.3.7.md 16.21 – phương án A):
 * K-02/K-03 of getTonightKpi count the rooms of LONG STAYS entered by hand (US-017 AC5a, `manualLongStay`) like
 * any sold night. The KPI formula does not change (it counts `stay_night` `sold` with a room – Q-02, one source of
 * nights); the AC5a booking must have its nights (`rate_source = lease_allocation`), generated by BE-A.
 *
 * !! EXPECTED RED until BE-A merges A7-01 (AC5a bookings get `stay_night` – ARC 16.21 "Việc BE-A"). Before that the
 * two long stays have no night: 4/9 = 44,4 % on 15/10 and 5/9 = 55,6 % on 16/10 (the A7 finding). Checked 18/10:
 * red at HEAD 7ac11a4 (occupiedRooms 4, 44,4 %, no night for 301/102); green on the working tree with BE-A's
 * uncommitted A7-01 change. Do not "fix" this test by changing the expected numbers or the KPI formula (ARC 16.21
 * rejects reading segments – phương án B).
 *
 * Data: the DS-0 layout by room (s4-a7-reconciliation.md mục 2) built through the HTTP API, dates moved into the
 * seeded month (rooms/parameters from 01/10/2026):
 * - 301 AC5a long stay, in house since 01/10; 102 AC5a long stay, in house since 05/10;
 * - 101 in house 13→17/10; 402 in house 14→18/10; 103 and 302 arriving 15/10 (confirmed); 202 arriving 16/10;
 * - 401 OOO [15/10, 17/10) active; 201, 203 empty.
 * Oracle (US-010 AC1 – the BL 3.2 example; DATA A7 T0/T2/T3): night 15/10 → 6 / (10 − 1 OOO) = 66,7 % (also at
 * 02:00 on 16/10, still business day 15/10 – BR-010); night 16/10 → 7/9 = 77,8 %.
 * Ports of BE-C zones in the check-in are fakes (as in dashboard-s4-bed.test.ts). Fake clock, FAKE data only.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import type { Database, Tx } from '../../src/db/database';
import { FrontdeskPorts } from '../../src/modules/frontdesk/internal/stay-support';
import type {
  CheckinDocumentStatus,
  FrontdeskGuestAccessPort,
  FrontdeskMinibarPort,
  FrontdeskRegistrationPort,
} from '../../src/modules/frontdesk/public/ports';
import { Client, type FeatureApp, P, startFeatureApp } from '../helpers/feature-app';
import {
  type BookingIds,
  seedBooking,
  seedGuestRow,
  touchSessions,
} from '../helpers/reservations-fixture';
import { HAS_DB, type TestTenant, appDatabase, createTenant } from '../helpers/tenant';

class FakeRegistration implements FrontdeskRegistrationPort {
  docs: CheckinDocumentStatus = {
    mainGuestDocument: true,
    documentCheckBlock: false,
    pendingOnlineCheckin: false,
    visaExpiresBeforeDeparture: false,
    passportExpiresDuringStay: false,
  };
  async checkinDocumentStatus(): Promise<CheckinDocumentStatus> {
    return this.docs;
  }
  async deadlinePreview(_tx: Tx, _id: string, at: Date): Promise<Date | null> {
    return new Date(at.getTime() + 12 * 3_600_000);
  }
  async onCheckedIn(_tx: Tx, _id: string, at: Date): Promise<Date | null> {
    return new Date(at.getTime() + 12 * 3_600_000);
  }
  async onCheckInUndone() {}
  async onDepartureChanged() {}
  async onRoomChanged() {}
  async onPartyChanged() {}
  async onPartyMemberRemoved() {}
  async onCheckedOut() {}
  async onReservationVoided() {}
  async earliestVisaValidUntil(): Promise<string | null> {
    return null;
  }
}
class FakeGuestAccess implements FrontdeskGuestAccessPort {
  async revokeAllForReservation(): Promise<number> {
    return 0;
  }
}
class FakeMinibar implements FrontdeskMinibarPort {
  async checkoutStatus() {
    return { required: false, checked: true };
  }
  async onCheckedOut() {
    return null;
  }
}

interface Booking {
  id: string;
  code: string;
  folioId: string;
}

describe.skipIf(!HAS_DB)(
  'A7-01 – K-02/K-03 with AC5a long stays (BE-D; red until BE-A A7-01)',
  () => {
    let db: Database;
    let fa: FeatureApp;
    let t: TestTenant;
    let ids: BookingIds;
    let guest: string;
    const c: Record<string, Client> = {};
    const b: Record<string, Booking> = {};

    beforeAll(async () => {
      db = appDatabase(6);
      t = await createTenant(db, { users: { fd: ['front_desk'], fdl: ['front_desk_lead'] } });
      ids = await seedBooking(db, t);
      guest = await seedGuestRow(db, t, { name: 'Khách Thử Dài Hạn' });
      fa = await startFeatureApp(db, {
        override: (bld) =>
          bld.overrideProvider(FrontdeskPorts).useFactory({
            factory: () =>
              new FrontdeskPorts(
                new FakeRegistration(),
                new FakeGuestAccess(),
                { encryptChild: async () => ({}) as never, destroy: async () => undefined },
                new FakeMinibar(),
              ),
          }),
      });
      for (const u of ['fd', 'fdl']) {
        c[u] = Client.of(fa, t, u);
        c[u]!.deviceToken = await t.deviceToken();
      }
      // The story starts on 01/10 (before the tenant's T0): devices trusted since September.
      await db.withContext(t.ctx(), (tx) =>
        tx.query(`UPDATE trusted_device SET created_at = '2026-09-01', expires_at = '2026-12-31'`),
      );
    });
    afterAll(async () => {
      await fa?.close();
      await db?.close();
    });

    const url = (path = '') => `${P(t)}${path}`;
    const at = async (iso: string) => {
      const d = new Date(iso);
      fa.clock.set(d);
      await touchSessions(db, t, d);
    };
    const q = async <R extends Record<string, unknown>>(sql: string, p: unknown[] = []) =>
      (await db.withContext(t.ctx(), (tx) => tx.query<R>(sql, p))).rows;

    /** POST /reservations; a short stay pays the deposit the server asks for (DEPOSIT_INSUFFICIENT → retry). */
    const book = async (room: string, arrival: string, departure: string, long?: number) => {
      const body: Record<string, unknown> = {
        roomId: ids.rooms[room],
        channelId: ids.channels.direct,
        directSource: 'zalo_phone',
        arrivalDate: arrival,
        departureDate: departure,
        adults: 1,
        bookerGuestId: guest,
        paymentModel: 'direct',
        ...(long
          ? {
              manualLongStay: {
                monthlyRentVnd: long,
                depositHeldVnd: long,
                externalContractRef: `TEST-A7-${room}`,
              },
            }
          : { initialPayment: { type: 'deposit', method: 'cash', amountVnd: 1_000_000 } }),
      };
      let res = await c.fd!.send('POST', url('/reservations'), body);
      if (res.statusCode !== 201 && res.json().depositRequiredVnd) {
        body.initialPayment = {
          type: 'deposit',
          method: 'cash',
          amountVnd: res.json().depositRequiredVnd,
        };
        res = await c.fd!.send('POST', url('/reservations'), body);
      }
      expect(res.statusCode, `${room} ${res.body}`).toBe(201);
      b[room] = res.json() as Booking;
      return b[room]!;
    };
    const checkIn = async (room: string, iso: string) => {
      await at(iso);
      const bk = b[room]!;
      const get = async () => (await c.fd!.get(url(`/reservations/${bk.id}`))).json();
      const due = (await get()).balanceDueVnd as number;
      if (due > 0) {
        const r = await c.fd!.send('POST', url(`/folios/${bk.folioId}/payments`), {
          type: 'charge',
          method: 'cash',
          amountVnd: due,
        });
        expect([200, 201], r.body).toContain(r.statusCode);
      }
      const r = await c.fd!.send(
        'POST',
        url(`/reservations/${bk.id}/actions/check-in`),
        { cardsIssued: 1, houseRulesSent: true, checkinTime: iso.slice(11, 16) },
        { 'if-match': `"${(await get()).version}"` },
      );
      expect(r.statusCode, `${room} check-in ${r.body}`).toBe(200);
    };
    const kpi = async () => {
      const res = await c.fd!.get(url('/dashboard/tonight'));
      expect(res.statusCode, res.body).toBe(200);
      return res.json();
    };

    it('setup: two AC5a long stays (301, 102) and five short stays in house / arriving; 401 OOO from 15/10', async () => {
      await at('2026-10-01T09:00:00+07:00');
      await book('301', '2026-10-01', '2027-01-01', 11_130_000);
      await book('102', '2026-10-05', '2027-01-05', 9_410_000);
      await book('101', '2026-10-13', '2026-10-17');
      await book('402', '2026-10-14', '2026-10-18');
      await book('103', '2026-10-15', '2026-10-17');
      await book('302', '2026-10-15', '2026-10-17');
      await book('202', '2026-10-16', '2026-10-18');
      const external = await q<{ id: string }>(
        'SELECT id FROM reservation WHERE external_contract AND id = ANY($1::uuid[])',
        [[b['301']!.id, b['102']!.id]],
      );
      expect(external).toHaveLength(2);
      await checkIn('301', '2026-10-01T14:00:00+07:00');
      await checkIn('102', '2026-10-05T14:00:00+07:00');
      await checkIn('101', '2026-10-13T14:00:00+07:00');
      await checkIn('402', '2026-10-14T14:00:00+07:00');
      await at('2026-10-15T06:30:00+07:00');
      const blk = await c.fd!.send('POST', url('/room-blocks'), {
        roomId: ids.rooms['401'],
        startDate: '2026-10-15',
        endDatePlanned: '2026-10-17',
        reason: 'Bình nóng lạnh rò nước',
      });
      expect(blk.statusCode, blk.body).toBe(201);
      expect(blk.json().status).toBe('active');
    });

    it('A7-01 precondition (BE-A, ARC 16.21): each AC5a long stay has its sold nights 15/10 and 16/10 in its room', async () => {
      const nights = await q<{ room_no: string; night: string }>(
        `SELECT rm.room_no, n.stay_date::text AS night FROM stay_night n JOIN room rm ON rm.id = n.room_id
        WHERE n.reservation_id = ANY($1::uuid[]) AND n.night_state = 'sold'
          AND n.stay_date IN ('2026-10-15', '2026-10-16')
        ORDER BY rm.room_no, n.stay_date`,
        [[b['301']!.id, b['102']!.id]],
      );
      expect(
        nights,
        'A7-01: chờ BE-A sinh stay_night cho đơn AC5a (ARC openapi-0.3.7.md 16.21) – đỏ cho tới khi gộp',
      ).toEqual([
        { room_no: '102', night: '2026-10-15' },
        { room_no: '102', night: '2026-10-16' },
        { room_no: '301', night: '2026-10-15' },
        { room_no: '301', night: '2026-10-16' },
      ]);
    });

    it('US-010 AC1 / K-02, K-03: night 15/10 → 6 / (10 − 1 OOO) = 66,7 % at 08:00 and still at 02:00 on 16/10 (BR-010); night 16/10 → 7/9 = 77,8 %', async () => {
      const expected15 = {
        businessDate: '2026-10-15',
        roomsTotal: 10,
        oooRooms: 1,
        availableRoomsNet: 9,
        occupiedRooms: 6,
        occupancyPct: 66.7,
      };
      await at('2026-10-15T08:00:00+07:00');
      expect(await kpi(), 'A7-01 T0 (DATA: 4/9 = 44,4 % before BE-A)').toMatchObject(expected15);
      await at('2026-10-16T02:00:00+07:00');
      expect(await kpi(), 'A7-01 T2 – business day 15/10').toMatchObject(expected15);
      await at('2026-10-16T08:00:00+07:00');
      expect(await kpi(), 'A7-01 T3 (DATA: 5/9 = 55,6 % before BE-A)').toMatchObject({
        businessDate: '2026-10-16',
        availableRoomsNet: 9,
        occupiedRooms: 7,
        occupancyPct: 77.8,
      });
    });
  },
);
